Criando uma função para calcular a mediana de um conjunto

x &lt;- c(5, 10, 15, 8, 6, 40, 35, 10, 2, 4)

minha_mediana &lt;- function(x){
  n &lt;- length(x)
  resto &lt;- n %% 2 
  #checar se é par ou impar 
if(resto == 0){ 
  #aqui a mediana é par 
  xord &lt;- sort(x)
  centro &lt;- xord[(n/2):(n/2+1)]
  mean(centro)

} else{
  #aqui vai ser mediana impar 
  xord &lt;- sort(x)
  xord[(n+1)/2]
}
}
# x é o único argumento da função
minha_mediana(x)

